    }

    protected abstract PassStrategy<T> createPassStrategy();

    protected abstract <A> SortExecutor<A> createExecutor();

    protected void sortArray(T[] arr) {
        SortTask<T> task = new ArraySortTask<>(arr, metrics);
        task.performSort(createPassStrategy(), createExecutor());
    }

    protected void sortList(List<T> list) {
        SortTask<T> task = new ListSortTask<>(list, metrics);
        task.performSort(createPassStrategy(), createExecutor());
    }
}

/**
