        System.out.println("Input:  [zebra, apple, mango, banana]");
        System.out.println("Sorted: " + strings);
        System.out.println("Stats:  " + sorter.getStatistics().toCompactString());
        System.out.println();
    }

    private static void demonstrateCustomComparator() {
        BubbleSort<String> sorter = new Builder<String>()
            .withComparator(String::compareTo)
            .trackMetrics(true)
            .build();
        List<String> data = new ArrayList<>(Arrays.asList("dog", "cat", "bird", "elephant"));
        sorter.sort(data);
        System.out.println("=== Custom Comparator ===");
        System.out.println("Input:  [dog, cat, bird, elephant]");
        System.out.println("Sorted: " + data);
        System.out.println("Stats:  " + sorter.getStatistics().toCompactString());
        System.out.println();
    }

    private static void demonstrateFastMode() {
        BubbleSort<Integer> sorter = Factory.createFast();
        Integer[] data = {5, 2, 8, 1, 9};
        sorter.sort(data);
        System.out.println("=== Fast Mode (No Metrics) ===");
